def shortest_path(graph: dict, start, end) -> tuple[float, list] | None:
    if start == end:
        return (0.0, [start])

    # Priority queue: (distance, path)
    pq = [(0.0, [start])]
    visited = set()

    while pq:
        dist, path = heapq.heappop(pq)
        current = path[-1]

        if current in visited:
            continue

        visited.add(current)

        if current == end:
            return (dist, path)

        # Explore neighbors
        neighbors = graph.get(current, {})
        for neighbor, weight in neighbors.items():
            new_dist = dist + weight
            new_path = path + [neighbor]
            heapq.heappush(pq, (new_dist, new_path))

